<?php
require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/admin-layout.php';admin_required();$allowed=['Pending','Awaiting Payment','Paid','Processing','Shipped','Completed','Cancelled'];if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$status=$_POST['status']??'';if(in_array($status,$allowed,true)){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);flash('Order status updated.');}redirect('orders.php');}$rows=$pdo->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll();admin_header('Orders');$f=get_flash();if($f)echo '<div class="notice">'.e($f['message']).'</div>'; ?><div class="admin-panel table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th>View</th></tr><?php foreach($rows as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['customer_name'])?><br><?=e($o['whatsapp'])?></td><td><?=e($o['created_at'])?></td><td><?=money((float)$o['total'])?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach($allowed as $s):?><option <?=($s===$o['status']?'selected':'')?>><?=e($s)?></option><?php endforeach;?></select><button>Save</button></form></td><td><a href="order-detail.php?id=<?=$o['id']?>">Details</a></td></tr><?php endforeach;?></table></div><?php admin_footer(); ?>
